<?php
$material=max(0,(int)($_GET['material']??0));$gov=is_string($_GET['governorate']??null)?$_GET['governorate']:'';$grade=is_string($_GET['grade']??null)?$_GET['grade']:'';
$rows=[];$p=[];$where="b.status='published' AND b.quantity_g>b.reserved_g AND m.active=1 AND h.active=1";
if ($material) {$where.=' AND b.material_id=?';$p[]=$material;}
if (isset(governorates()[$gov])) {$where.=' AND h.governorate=?';$p[]=$gov;}
if(in_array($grade,['A','B','C'],true)){$where.=' AND b.grade=?';$p[]=$grade;}
$pn=max(1,min(10000,(int)($_GET['p']??1)));$offset=($pn-1)*12;$count=0;
if(ready()){$count=(int)Db::scalar('SELECT COUNT(*) FROM batches b JOIN materials m ON m.id=b.material_id JOIN hubs h ON h.id=b.hub_id WHERE '.$where,$p);$rows=Db::all('SELECT b.*,m.name_ar,m.name_en,m.icon,h.name_ar AS hub_ar,h.name_en AS hub_en,h.governorate FROM batches b JOIN materials m ON m.id=b.material_id JOIN hubs h ON h.id=b.hub_id WHERE '.$where.' ORDER BY b.created_at DESC LIMIT 12 OFFSET '.$offset,$p);}
?>
<section class="page-hero container"><div class="eyebrow"><?= t('موارد واضحة. خيارات أفضل.','CLEAR RESOURCES. BETTER CHOICES.') ?></div><h1><?= t('سوق المواد الزراعية','The materials marketplace') ?></h1><p><?= t('دفعات مفحوصة وكميات متاحة، مع السعر لكل طن. تكلفة النقل ورسوم الخدمة تظهر في مراجعة الطلب.','Inspected batches and available quantities, priced per tonne. Transport and service costs appear in your order review.') ?></p></section>
<section class="container page-section"><form method="get" class="filter-bar"><input type="hidden" name="page" value="market"><label class="field"><span><?= t('نوع المادة','Material') ?></span><select name="material"><option value=""><?= t('كل المواد','All materials') ?></option><?php foreach(catalogue_materials() as $m): ?><option value="<?= $m['id'] ?>" <?= $material===(int)$m['id']?'selected':'' ?>><?= e(localized($m)) ?></option><?php endforeach; ?></select></label><label class="field"><span><?= t('المحافظة','Governorate') ?></span><select name="governorate"><option value=""><?= t('كل المحافظات','All governorates') ?></option><?= gov_options($gov) ?></select></label><label class="field"><span><?= t('درجة الفحص','Physical grade') ?></span><select name="grade"><option value=""><?= t('كل الدرجات','All grades') ?></option><?php foreach(['A','B','C'] as $g): ?><option <?= $grade===$g?'selected':'' ?>><?= $g ?></option><?php endforeach; ?></select></label><button class="button button-green" type="submit"><?= icon('search') ?><?= t('اعرض النتائج','Show results') ?></button></form><div class="market-result-heading"><span><?= $count ?> <?= t('دفعة متاحة','available batches') ?></span><span><?= icon('shield') ?><?= t('كميات بعد الفحص','Post-inspection stock') ?></span></div>
<?php if(!$rows): ?><div class="empty-state"><?= icon('wheat') ?><h2><?= t('الحصاد الجديد في الطريق.','A new harvest is on the way.') ?></h2><p><?= t('لا توجد دفعات متاحة لهذه الاختيارات حالياً. ابعت احتياج مصنعك، وفريق حصاد يتابع معك.','There are no available batches for these filters yet. Send your factory requirements and Hasad will follow up.') ?></p><a href="<?= e(url('contact')) ?>" class="button button-green"><?= t('سجّل احتياجك','Tell us what you need') ?></a></div><?php else: ?><div class="listing-grid"><?php foreach($rows as $i=>$b): ?><article class="listing-card"><div class="listing-art material-art-<?= $i%5 ?>"><?= icon($b['icon']) ?><span class="badge badge-published"><?= t('درجة','Grade') ?> <?= e($b['grade']) ?></span></div><div class="listing-body"><div class="listing-meta"><span><?= e(gov_label($b['governorate'])) ?></span><small><?= e($b['code']) ?></small></div><h2><?= e(localized($b)) ?></h2><p><?= e($b['hub_'.lang()]) ?></p><div class="listing-stats"><div><small><?= t('الكمية المتاحة','Available quantity') ?></small><b><?= qty((int)$b['quantity_g']-(int)$b['reserved_g']) ?></b></div><div><small><?= t('سعر الطن','Price per tonne') ?></small><b><?= money((int)$b['price_per_tonne']) ?></b></div></div><a class="button button-green button-full" href="<?= e(url('checkout',['id'=>$b['id']])) ?>"><?= t('عرض التفاصيل وطلب المادة','View details & order') ?><?= icon('arrow') ?></a></div></article><?php endforeach; ?></div><?php endif; ?>
<?php if($count>12): ?><div class="pagination"><?php if($pn>1): ?><a class="button button-outline button-small" href="<?= e(url('market',['material'=>$material,'governorate'=>$gov,'grade'=>$grade,'p'=>$pn-1])) ?>"><?= t('السابق','Previous') ?></a><?php endif; ?><span><?= $pn ?> / <?= (int)ceil($count/12) ?></span><?php if($pn*12<$count): ?><a class="button button-outline button-small" href="<?= e(url('market',['material'=>$material,'governorate'=>$gov,'grade'=>$grade,'p'=>$pn+1])) ?>"><?= t('التالي','Next') ?></a><?php endif; ?></div><?php endif; ?><div class="note"><?= icon('shield') ?><p><?= t('فحصنا يوضح الوزن والرطوبة والملاحظات الميدانية. استخدام المادة في الأعلاف أو التطبيقات المتخصصة يحتاج اعتماد المشتري والفحوص ذات الصلة.','Our inspection records weight, moisture and field observations. Feed or specialist use requires buyer acceptance and relevant testing.') ?></p></div></section>
